<template><div><component :is="componentFor(panel.panel_type)" v-for="panel in dashboard?.panels" :key="panel.id" :result="results.get(panel.id)?.result" :state="results.get(panel.id)?.error?'partial':undefined" :unit="panel.unit"/></div></template>
<script setup lang="ts">
import{inject,onBeforeUnmount,onMounted,ref}from'vue';import type{ObservabilityQueryApi}from'@/api/observability/query';import type{Dashboard,QueryItemResult}from'@/types/observability';import TimeSeriesPanel from'../components/TimeSeriesPanel.vue';import StatPanel from'../components/StatPanel.vue';import TablePanel from'../components/TablePanel.vue';import{createRefreshController,groupPanelQueries}from'./dashboard-utils';const props=defineProps<{dashboard:Dashboard}>();const api=inject<ObservabilityQueryApi>('observabilityQueryApi')!;const results=ref(new Map<number,QueryItemResult>());async function load(signal:AbortSignal){for(const [datasource_id,queries]of groupPanelQueries(props.dashboard.panels)){const batch=await api.instant({datasource_id,enrich_assets:false,queries},signal);for(const item of batch.results){const id=Number(item.ref_id.replace('panel-',''));results.value.set(id,item)}}}const refresh=createRefreshController(load,()=>document.visibilityState==='hidden');let timer:number|undefined;function visibility(){refresh.setHidden(document.visibilityState==='hidden');if(document.visibilityState==='visible')void refresh.refresh()}function componentFor(type:string){return type==='stat'?StatPanel:type==='table'?TablePanel:TimeSeriesPanel}onMounted(()=>{void refresh.refresh();timer=window.setInterval(()=>void refresh.refresh(),props.dashboard.refresh_interval_s*1000);document.addEventListener('visibilitychange',visibility)});onBeforeUnmount(()=>{if(timer)clearInterval(timer);document.removeEventListener('visibilitychange',visibility);refresh.dispose()})
</script>
